+function updateQuestProgress(){save.kills=(save.kills||0)+1;save.weeklies.fire=Math.min(5,(save.weeklies.fire||0)+1);save.weeklies.water=Math.min(5,(save.weeklies.water||0)+1);save.weeklies.earth=Math.min(5,(save.weeklies.earth||0)+1);save.weeklies.wind=Math.min(5,(save.weeklies.wind||0)+1);if(save.kills===5){save.xp+=120;save.gold+=80;log('✦ Jornada concluída! <b>+120 EXP · +80 ouro</b>')}for(const id of ['fire','water','earth','wind'])if(save.weeklies[id]===5&&!save.weeklies[id+'Claim']){save.weeklies[id+'Claim']=true;save.tickets++;log('✧ Missão semanal concluída! <b>+1 ticket</b>')}save.xp+=22;if(save.xp>=levelMax){save.xp-=levelMax;save.level++;levelMax=Math.floor(levelMax*1.35);save.hp=cls.hp+save.level*12;save.mp=cls.mp+save.level*5;log('🌟 Subiu para o nível <b>'+save.level+'</b>!')}save.gold+=8;save.hp=Math.min(cls.hp+save.level*12,save.hp+5);save.mp=Math.min(cls.mp+save.level*5,save.mp+3);saveGame()}
