+function drawSkills(){const el=document.getElementById('skills');el.innerHTML='';const icons=cls.id==='mage'?['🔥','❄️','⚡','☄️']:cls.id==='cleric'?['✨','☀️','🛡️','🌟']:cls.id==='archer'?['🏹','➶','🍃','🌠']:['⚔️','🌀','💨','🌑'];for(let i=0;i<4;i++){const b=document.createElement('button');b.className='skill';b.innerHTML='<span class="skill-label">'+cls.skill[i]+'</span>'+icons[i]+'<small>'+(i+1)+'</small><div class="cd"></div>';b.onclick=()=>castSkill(i);el.appendChild(b)}}
