+function onWorldClick(ev){if(ev.target.closest('button')||ev.target.closest('.panel'))return;const pointer=new THREE.Vector2((ev.clientX/innerWidth)*2-1,-(ev.clientY/innerHeight)*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(pointer,camera);const hits=ray.intersectObjects(enemies.filter(e=>!e.userData.dead),true);if(hits.length){let o=hits[0].object;while(o.parent&&!o.userData.hp)o=o.parent;if(o.userData.hp)selectEnemy(o)}}
+function damageEnemy(amount,element='arcane',skill=false){if(!target||target.userData.dead){target=enemies.find(e=>!e.userData.dead);if(!target){log('Nenhum alvo por perto.');return}}const dist=player.position.distanceTo(target.position);if(dist>(skill?10:4.2)){log('Aproxime-se do alvo!');return}const crit=Math.random()<.12,dmg=Math.round(amount*(crit?1.7:1));target.userData.hp=Math.max(0,target.userData.hp-dmg);const data=enemies.find(e=>e.mesh===target);if(data){data.label.ctx.clearRect(0,0,220,44);data.label.ctx.fillStyle='#13242a';data.label.ctx.roundRect(2,12,216,18,8);data.label.ctx.fill();data.label.ctx.fillStyle=target.userData.boss?'#cf7781':'#95c77e';data.label.ctx.roundRect(4,14,212*Math.max(0,target.userData.hp/target.userData.maxHp),14,6);data.label.ctx.fill();data.label.ctx.fillStyle='#f3e8cc';data.label.ctx.font='bold 15px sans-serif';data.label.ctx.textAlign='center';data.label.ctx.fillText(target.userData.boss?'GUARDIÃO DO BOSQUE':'Mofinho silvestre',110,10);data.label.tex.needsUpdate=true}makeHitEffect(target.position.clone().add(new THREE.Vector3(0,1,0)),element,dmg,crit);if(crit)log('CRÍTICO! <b>'+dmg+'</b> de dano');if(target.userData.hp<=0){const dead=target;dead.userData.dead=true;scene.remove(dead);save.gold+=dead.userData.boss?150:12;save.xp+=dead.userData.boss?170:26;if(dead.userData.boss){save.bossKills++;save.weeklies.boss=1;save.tickets+=2;log('🐉 Guardião derrotado! <b>+2 tickets · +150 ouro</b>');if(!save.weeklies.bossClaim){save.weeklies.bossClaim=true;save.tickets+=2}}else{log('✧ Criatura derrotada · <b>+12 ouro · +26 EXP</b>');updateQuestProgress()}if(save.xp>=levelMax){save.xp-=levelMax;save.level++;levelMax=Math.floor(levelMax*1.35);log('🌟 Subiu para o nível <b>'+save.level+'</b>!')}setTimeout(()=>dead.userData.boss?spawnEnemy(0,true):spawnEnemy(0),5500);target=null;saveGame()}else saveGame()}
+function makeHitEffect(pos,element,dmg,crit){const color={fire:0xff744e,ice:0x81d8f4,lightning:0xffe87d,light:0xfff0a2,shadow:0xb38be8,wind:0xa7ebce,earth:0xa8c677,arcane:0x78ded7}[element]||0x8be5ce;const m=new THREE.Mesh(new THREE.IcosahedronGeometry(crit?.38:.23,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.position.copy(pos);scene.add(m);effects.push({mesh:m,life:.55,max:.55,scale:.1});const c=document.createElement('canvas');c.width=128;c.height=54;const ctx=c.getContext('2d');ctx.font='bold 34px sans-serif';ctx.textAlign='center';ctx.fillStyle=crit?'#ffdc84':'#f6fff1';ctx.shadowColor='#202c21';ctx.shadowBlur=5;ctx.fillText(''+dmg,64,38);const spr=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthTest:false}));spr.position.copy(pos);spr.position.y+=.45;spr.scale.set(.8,.35,1);scene.add(spr);effects.push({mesh:spr,life:.8,max:.8,float:true})}
+function castSkill(i){if(uiCooldown[i]>0)return;if(!target||target.userData.dead)selectEnemy(enemies.find(e=>!e.userData.dead));const costs=[10,13,16,24];if(save.mp<costs[i]){log('MP insuficiente.');return}save.mp-=costs[i];uiCooldown[i]=[3,5,7,12][i];const elements=cls.id==='mage'?['fire','ice','lightning','arcane']:cls.id==='cleric'?['light','light','wind','light']:cls.id==='assassin'?['shadow','wind','shadow','shadow']:['wind','earth','wind','arcane'];player.rotation.y=Math.atan2((target?.position.x||0)-player.position.x,(target?.position.z||0)-player.position.z);log('✨ <b>'+cls.skill[i]+'</b>!');damageEnemy(cls.attack*(i===3?4.3:i===2?2.2:1.55)+save.level*5,elements[i],true);saveGame();const b=document.querySelectorAll('.skill')[i];b.classList.add('cooling');b.querySelector('.cd').textContent=uiCooldown[i]+'s';const t=setInterval(()=>{uiCooldown[i]--;if(uiCooldown[i]<=0){clearInterval(t);b.classList.remove('cooling')}else b.querySelector('.cd').textContent=uiCooldown[i]+'s'},1000)}
+function basicAttack(){const now=performance.now();if(now-lastAttack<600)return;lastAttack=now;if(!target||target.userData.dead)selectEnemy(enemies.find(e=>!e.userData.dead));if(target){player.rotation.y=Math.atan2(target.position.x-player.position.x,target.position.z-player.position.z);damageEnemy(cls.attack+save.level*2,'arcane',false)}}
