function dodge(){if(player.userData.dodge)return;player.userData.dodge=.32;const dir=new THREE.Vector3(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));player.position.addScaledVector(dir,1.9);log('💨 Esquiva!')}
const panel=document.getElementById('panel');function openPanel(type){panel.classList.add('open');renderPanel(type)}function closePanel(){panel.classList.remove('open')}
function renderPanel(type){const title=document.getElementById('modalTitle'),sub=document.getElementById('modalSub'),body=document.getElementById('modalBody');if(type==='character'){title.textContent='Herói da Clareira';sub.textContent='Sua jornada, seu estilo. Toda classe tem seu lugar.';body.innerHTML='<div class="tabs"><button class="tab selected">Aventureira</button><button class="tab" id="classesTab">Classes</button></div><div class="grid"><div class="card"><div class="icon">🧝</div><h4>'+cls.name+' · Nv. '+save.level+'</h4><p>'+cls.desc+'</p><div class="meta">HP '+(cls.hp+save.level*12)+' · MP '+(cls.mp+save.level*5)+' · ATQ '+(cls.attack+save.level*2)+'</div></div><div class="card"><div class="icon">🧥</div><h4>'+save.equipped+'</h4><p>Visual cosmético equipado. Aparência sem atributos de combate.</p><div class="meta">✧ Cosmético · Nenhum bônus de status</div></div><div class="card"><div class="icon">✨</div><h4>Talentos de classe</h4><p>'+cls.skill.map((s,i)=>(i+1)+'. '+s).join('<br>')+'</p><div class="meta">Especialização desbloqueia no nível 20</div></div><div class="card"><div class="icon">📜</div><h4>Conquistas</h4><p>'+save.kills+' criaturas derrotadas<br>'+save.bossKills+' guardiões vencidos</p><div class="meta">Exploradora de Lúmen</div></div></div>';body.querySelector('#classesTab').onclick=()=>renderPanel('classes')}
else if(type==='classes'){title.textContent='Escolha sua classe';sub.textContent='Troque livremente na Clareira. Progresso compartilhado; estilo novo.';body.innerHTML='<div class="class-options">'+classes.map(c=>'<button class="class-choice '+(c.id===cls.id?'selected':'')+'" data-class="'+c.id+'"><span>'+c.icon+'</span><strong>'+c.name+'</strong><small>'+c.desc+'</small></button>').join('')+'</div>';body.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{cls=classes.find(c=>c.id===b.dataset.class);save.classId=cls.id;scene.remove(player);player=makePlayer();player.position.copy(camera.position.clone().setY(0));player.position.set(0,0,2);scene.add(player);drawSkills();save.hp=Math.min(save.hp,cls.hp+save.level*12);save.mp=Math.min(save.mp,cls.mp+save.level*5);saveGame();renderPanel('classes');log('Classe alterada: <b>'+cls.name+'</b>')})}
else if(type==='quests'){title.textContent='Diário de aventura';sub.textContent='Missões semanais · reiniciam toda segunda-feira (protótipo local).';body.innerHTML='<div class="notice">🎁 Complete as atividades jogando normalmente. Tickets gratuitos — sem anúncios ou compras. Recompensas puramente cosméticas.</div><div class="grid" style="margin-top:11px">'+quests.map(q=>{let done=q.id==='all'?['fire','water','earth','wind','boss'].every(id=>save.weeklies[id+'Claim']):q.id==='login'?!!save.weeklies.loginClaim:!!save.weeklies[q.id+'Claim'];let progress=q.id==='login'?(save.weeklies.login?1:0):q.id==='boss'?(save.weeklies.boss||0):q.id==='all'?(done?1:0):(save.weeklies[q.id]||0);return '<div class="card"><div class="icon">'+q.icon+'</div><h4>'+q.name+'</h4><p>'+q.desc+'</p><div class="meta">'+(q.id==='all'?'🎟 '+q.reward+' tickets bônus':'🎟 '+q.reward+' ticket')+' · '+progress+'/'+q.goal+'</div><button class="cta" style="margin-top:9px" data-claim="'+q.id+'" '+(done?'disabled':'')+'>'+(done?'CONCLUÍDA':progress>=q.goal?'RESGATAR':'EM ANDAMENTO')+'</button></div>'}).join('')+'</div>';body.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{const id=b.dataset.claim;if(id==='login'){save.weeklies.login=1;save.weeklies.loginClaim=true;save.tickets++}else if(id==='all'){save.weeklies.allClaim=true;save.tickets+=5}else if(id==='boss'){save.weeklies.bossClaim=true;save.tickets+=2}else if(save.weeklies[id]>=5){save.weeklies[id+'Claim']=true;save.tickets++}saveGame();renderPanel('quests');log('🎟 Recompensa semanal resgatada!')})}
else if(type==='gacha'){title.textContent='Ateliê dos desejos';sub.textContent='Banners gratuitos · itens visuais sem atributos ou vantagens.';body.innerHTML='<div class="banner"><div><div class="eyebrow">BANNER EM DESTAQUE · 06 DIAS</div><h3>Fábulas do bosque</h3><p>Roupas, asas e auras encantadas.</p><button class="cta" id="pull">✧ INVOCAR · 1 TICKET</button></div><div class="banner-art">🪽</div></div><div class="prob"><b>Probabilidades por tentativa:</b> Incomum 43% · Raro 28% · Épico 17% · Lendário 9% · Mítico 3%.<br>Pity: item Épico+ garantido em 10 tentativas; Lendário+ em 20. Itens repetidos viram fragmentos. Nenhuma compra disponível.</div><div class="notice">✧ Seus tickets: <b>'+save.tickets+'</b> · Proteção contra azar: <b>'+save.pity+'/20</b> · Fragmentos: <b>'+save.shards+'</b></div><h3 style="font:15px var(--serif);margin:18px 0 9px">Coleção · '+save.owned.length+'/'+cosmetics.length+'</h3><div class="grid">'+cosmetics.map(c=>'<div class="card"><div class="icon">'+c.icon+'</div><h4>'+c.name+'</h4><p>'+c.rarity+' · visual exclusivo</p><div class="meta">'+(save.owned.includes(c.name)?(save.equipped===c.name?'✓ EQUIPADO':'DESBLOQUEADO'):'🔒 '+c.rate+'%')+'</div>'+(save.owned.includes(c.name)&&save.equipped!==c.name?'<button class="cta" style="margin-top:8px" data-equip="'+c.name+'">EQUIPAR</button>':'')+'</div>').join('')+'</div>';body.querySelector('#pull').onclick=drawGacha;body.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{save.equipped=b.dataset.equip;saveGame();renderPanel('gacha')})}}
function drawGacha(){if(save.tickets<1){log('Complete missões semanais para ganhar tickets gratuitos.');return}save.tickets--;save.pity++;let item;if(save.pity>=20){item=cosmetics[4];save.pity=0}else if(save.pity>=10&&Math.random()<.2){item=cosmetics[2+Math.floor(Math.random()*3)];save.pity=0}else{let n=Math.random()*100;item=cosmetics.find(c=>(n-=c.rate)<=0)||cosmetics[0]}const dupe=save.owned.includes(item.name);if(dupe){const f={Incomum:5,Raro:12,Épico:30,Lendário:75,Mítico:150}[item.rarity];save.shards+=f;log('✧ '+item.icon+' <b>'+item.name+'</b> repetido · +'+f+' fragmentos')}else{save.owned.push(item.name);save.equipped=item.name;log('🎉 NOVO VISUAL! '+item.icon+' <b>'+item.name+'</b> · '+item.rarity)}if(['Lendário','Mítico'].includes(item.rarity))save.pity=0;saveGame();renderPanel('gacha')}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));document.getElementById('closePanel').onclick=closePanel;panel.addEventListener('click',e=>{if(e.target===panel)closePanel()});document.getElementById('attack').onclick=basicAttack;document.getElementById('dodge').onclick=dodge;document.getElementById('potion').onclick=()=>{if(save.hp>=cls.hp+save.level*12){log('HP já está cheio.');return}save.hp=Math.min(cls.hp+save.level*12,save.hp+45);save.mp=Math.min(cls.mp+save.level*5,save.mp+18);log('🧪 Poção usada · <b>+45 HP · +18 MP</b>');saveGame()};

