 for(const id of ['fire','water','earth','wind'])await click('[data-claim="'+id+'"]');await click('[data-claim="all"]');
 await click('[data-claim="boss"]');const quests=await page.evaluate(()=>JSON.parse(localStorage.getItem('eterna-save-v1')));
