 await open('gacha');await click('#pull');const tenPull=await page.evaluate(()=>JSON.parse(localStorage.getItem('eterna-save-v1')));
 await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('eterna-save-v1'));s.pity=19;s.tickets=1;localStorage.setItem('eterna-save-v1',JSON.stringify(s))});await page.reload({waitUntil:'networkidle'});await open('gacha');await click('#pull');const twentyPull=await page.evaluate(()=>JSON.parse(localStorage.getItem('eterna-save-v1')));
 // Skill has 10-unit range; basic attacks are checked after enemies approach.
 await page.reload({waitUntil:'networkidle'});await page.locator('.skill').nth(0).click();await page.waitForTimeout(150);await page.waitForTimeout(6500);await page.locator('#attack').click();await page.waitForTimeout(150);await page.locator('.skill').nth(1).click();await page.waitForTimeout(150);const combat=await page.locator('#combatLog').innerText();
